import ee, math, sys
ee.Initialize(project='earthsense-436113')

# Geometry: NYC bbox
nyc = ee.Geometry.Polygon(
    [[[-74.30, 40.46], [-73.65, 40.46], [-73.65, 41.00], [-74.30, 41.00], [-74.30, 40.46]]],
    None, False
)

# UTC windows for 2023-08-09 (EDT = UTC-4)
win1 = ('2023-08-09T18:00:00', '2023-08-09T19:00:00')  # 2-3 pm EDT
win2 = ('2023-08-09T21:00:00', '2023-08-09T22:00:00')  # 5-6 pm EDT

collections_try = [
    'COPERNICUS/S5P/OFFL/L2_NO2',
    'COPERNICUS/S5P/NRTI/L2_NO2',
    'COPERNICUS/S5P/OFFL/L3_NO2',
    'COPERNICUS/S5P/NRTI/L3_NO2',
]

def get_window_stats(geom, start, end, label):
    any_accessible = False
    last_perm_err = None
    for col_id in collections_try:
        try:
            col = ee.ImageCollection(col_id).filterBounds(geom).filterDate(start, end)
            size = col.size().getInfo()
            any_accessible = True
            print(f"{label} {col_id} images: {size}")
            if size == 0:
                continue

            first = ee.Image(col.first())
            bands = first.bandNames().getInfo()
            use_cf = 'cloud_fraction' in bands
            band = 'tropospheric_NO2_column_number_density'

            def mask_fn(img):
                m = ee.Image(1)
                if 'qa_value' in bands:
                    m = m.And(img.select('qa_value').gte(0.75))
                if use_cf:
                    m = m.And(img.select('cloud_fraction').lt(0.2))
                return img.updateMask(m)

            img = col.map(mask_fn).mosaic()

            # Valid pixel count
            count = img.select(band).reduceRegion(
                reducer=ee.Reducer.count(),
                geometry=geom,
                scale=3000,
                maxPixels=1e9
            ).get(band).getInfo()

            if (count is None) or int(count) == 0:
                print(f"{label} Valid Pixels: 0")
                return {'status': 'C2'}

            # Mean NO2
            mean_val = img.select(band).reduceRegion(
                reducer=ee.Reducer.mean(),
                geometry=geom,
                scale=3000,
                maxPixels=1e9
            ).get(band).getInfo()

            if (mean_val is None) or (not math.isfinite(mean_val)):
                print(f"{label} Mean NO2: None/NaN")
                return {'status': 'C3'}

            cloud_mean = None
            if use_cf:
                cloud_mean = img.select('cloud_fraction').reduceRegion(
                    reducer=ee.Reducer.mean(),
                    geometry=geom,
                    scale=3000,
                    maxPixels=1e9
                ).get('cloud_fraction').getInfo()

            if cloud_mean is not None:
                print(f"{label} Valid Pixels: {int(count)}, Mean NO2 (mol/m²): {float(mean_val):.6f}, Cloud mean: {float(cloud_mean):.3f}")
            else:
                print(f"{label} Valid Pixels: {int(count)}, Mean NO2 (mol/m²): {float(mean_val):.6f}")
            return {'status': 'OK', 'val': float(mean_val), 'count': int(count), 'col': col_id}

        except Exception as e:
            msg = str(e)
            last_perm_err = msg
            print(f"{label} Error with {col_id}: {msg[:110]}")
            continue

    # If we couldn't access any collection at all, it's a D error; otherwise it's C1 (no images in time window)
    if not any_accessible and last_perm_err:
        return {'status': 'D'}
    return {'status': 'C1'}

def emit(tag):
    print(tag)
    sys.exit(0)

# Run for both windows
res1 = get_window_stats(nyc, win1[0], win1[1], "14-15 EDT")
res2 = get_window_stats(nyc, win2[0], win2[1], "17-18 EDT")

# Handle outcomes
for r in (res1, res2):
    if r['status'] == 'D':
        emit('D')
if res1['status'] == 'C1' or res2['status'] == 'C1':
    emit('C1')
if res1['status'] == 'C2' or res2['status'] == 'C2':
    emit('C2')
if res1['status'] == 'C3' or res2['status'] == 'C3':
    emit('C3')

# Compare means
v1, v2 = res1['val'], res2['val']
print(f"Comparison NO2 14-15 vs 17-18 (mol/m²): {v1:.6f} vs {v2:.6f}")
emit('A' if v1 > v2 else 'B')

