import ee, math, sys
ee.Initialize(project='earthsense-436113')

# NYC bounding box
nyc = ee.Geometry.Polygon(
    [[[-74.30, 40.46], [-73.65, 40.46], [-73.65, 41.00], [-74.30, 41.00], [-74.30, 40.46]]],
    None, False
)

# UTC windows for 2023-08-09 (EDT = UTC-4)
win1 = ('2023-08-09T18:00:00', '2023-08-09T19:00:00')  # 2-3 pm EDT
win2 = ('2023-08-09T21:00:00', '2023-08-09T22:00:00')  # 5-6 pm EDT

def emit(tag):
    print(tag)
    sys.exit(0)

def summarize(img, band, geom, scale, label, extra_bands=None):
    # Count valid pixels
    count = img.select(band).reduceRegion(
        reducer=ee.Reducer.count(),
        geometry=geom,
        scale=scale,
        maxPixels=1e9
    ).get(band).getInfo()
    if (count is None) or int(count) == 0:
        return {'status':'C2'}
    # Mean value
    mean_val = img.select(band).reduceRegion(
        reducer=ee.Reducer.mean(),
        geometry=geom,
        scale=scale,
        maxPixels=1e9
    ).get(band).getInfo()
    if (mean_val is None) or (not math.isfinite(mean_val)):
        return {'status':'C3'}
    out = {'status':'OK', 'val': float(mean_val), 'count': int(count), 'extra': {}}
    if extra_bands:
        for eb in extra_bands:
            mv = img.select(eb).reduceRegion(
                reducer=ee.Reducer.mean(),
                geometry=geom,
                scale=scale,
                maxPixels=1e9
            ).get(eb).getInfo()
            out['extra'][eb] = None if mv is None else float(mv)
    return out

def try_s5p(geom, start, end, label, verbose=False):
    # S5P L3 collections (public)
    col_ids = ['COPERNICUS/S5P/OFFL/L3_NO2', 'COPERNICUS/S5P/NRTI/L3_NO2']
    for col_id in col_ids:
        try:
            col = ee.ImageCollection(col_id).filterBounds(geom).filterDate(start, end)
            size = col.size().getInfo()
        except Exception as e:
            continue
        if size == 0:
            continue
        first = ee.Image(col.first())
        bands = first.bandNames().getInfo()
        band = 'tropospheric_NO2_column_number_density' if 'tropospheric_NO2_column_number_density' in bands else None
        if band is None:
            continue
        use_cf = 'cloud_fraction' in bands
        use_qa = 'qa_value' in bands
        def mask_fn(img):
            m = ee.Image(1)
            if use_qa:
                m = m.And(img.select('qa_value').gte(0.75))
            if use_cf:
                m = m.And(img.select('cloud_fraction').lt(0.2))
            return img.updateMask(m)
        img = col.map(mask_fn).mosaic()
        res = summarize(img, band, geom, 3000, label, extra_bands=['cloud_fraction'] if use_cf else None)
        if res['status'] == 'OK':
            res['dataset'] = col_id
            return res
        else:
            return res  # C2 or C3
    return {'status':'C1'}

def try_cams(geom, start, end, label):
    # Try multiple CAMS IDs to avoid D
    cams_ids = ['ECMWF/CAMS/NRT', 'ECMWF/CAMS/Global_atmospheric_composition_forecasts']
    last_err = None
    for cid in cams_ids:
        try:
            col = ee.ImageCollection(cid).filterBounds(geom).filterDate(start, end)
            size = col.size().getInfo()
        except Exception as e:
            last_err = str(e)
            continue
        if size == 0:
            continue
        first = ee.Image(col.first())
        bands = first.bandNames().getInfo()
        candidates = [
            'total_column_nitrogen_dioxide',
            'nitrogendioxide_column_number_density',
            'tcno2','gtno2','no2_total_column','NO2_column_number_density'
        ]
        band = next((b for b in candidates if b in bands), None)
        if band is None:
            continue
        img = col.mosaic()
        res = summarize(img, band, geom, 20000, label)
        if res['status'] == 'OK':
            res['dataset'] = cid
            res['band'] = band
            return res
        else:
            return res
    return {'status':'C1' if last_err is None else 'D'}

# First try S5P for both windows
r1 = try_s5p(nyc, win1[0], win1[1], "14-15 EDT")
r2 = try_s5p(nyc, win2[0], win2[1], "17-18 EDT")

use = None
if r1.get('status') == 'OK' and r2.get('status') == 'OK':
    use = 'S5P'
else:
    # Fallback to hourly CAMS for both windows to ensure comparability
    r1 = try_cams(nyc, win1[0], win1[1], "14-15 EDT")
    r2 = try_cams(nyc, win2[0], win2[1], "17-18 EDT")
    if r1.get('status') == 'OK' and r2.get('status') == 'OK':
        use = 'CAMS'

# Handle failure cases
for r in (r1, r2):
    if r['status'] == 'D':
        emit('D')
if r1['status'] == 'C1' or r2['status'] == 'C1':
    emit('C1')
if r1['status'] == 'C2' or r2['status'] == 'C2':
    emit('C2')
if r1['status'] == 'C3' or r2['status'] == 'C3':
    emit('C3')

# Print concise evidence and answer
if use == 'S5P':
    print("Using: S5P L3 NO2")
    cf1 = r1['extra'].get('cloud_fraction') if r1.get('extra') else None
    cf2 = r2['extra'].get('cloud_fraction') if r2.get('extra') else None
    print(f"14-15 EDT Pixels: {r1['count']}, Mean NO2 (mol/m²): {r1['val']:.6e}, Cloud mean: {cf1:.3f}" if cf1 is not None else f"14-15 EDT Pixels: {r1['count']}, Mean NO2 (mol/m²): {r1['val']:.6e}")
    print(f"17-18 EDT Pixels: {r2['count']}, Mean NO2 (mol/m²): {r2['val']:.6e}, Cloud mean: {cf2:.3f}" if cf2 is not None else f"17-18 EDT Pixels: {r2['count']}, Mean NO2 (mol/m²): {r2['val']:.6e}")
else:
    print(f"Using: {r1['dataset']} ({r1.get('band','NO2')})")
    print(f"14-15 EDT Pixels: {r1['count']}, Mean NO2: {r1['val']:.6e}")
    print(f"17-18 EDT Pixels: {r2['count']}, Mean NO2: {r2['val']:.6e}")

print(f"Comparison NO2 14-15 vs 17-18: {r1['val']:.6e} vs {r2['val']:.6e}")
print('A' if r1['val'] > r2['val'] else 'B')
